head.script:
scwin.screenId = "jldfil59410";

///////// 1. 변수 및 선언 영역 /////////

scwin.uploadCode = "0";

scwin.form = null;

scwin.agnccomMbr = 1;

scwin.selExcInst = 1;


///////// 2. 초기화 영역 /////////

// 화면 진입점 — 2구역 최상단 단일 정의, init_* 를 데이터 의존성 순서로 순차 호출한다.
/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 파라미터 수신부터 신규/조회 분기 본문 초기화까지 init_* 단계를 데이터 의존성 순서로 순차 실행한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = async function() {
    try {
        scwin.init_recvParam(); // 1) 화면 전환 파라미터 수신 (dma_pageContext)
        scwin.init_nowVars(); // 2) 서버 현재일(today) 충전
        scwin.init_fillGen(); // 3) 기타서류 첨부목록(dlt_attachList14) 제너레이터 채움
        scwin.init_rowCopy(); // 4) loadTp·법인등록번호·첨부파일명 표시 복사
        scwin.init_attrReals(); // 5) txa_remk 라벨 동적 렌더
        scwin.init_conds(); // 6) 버튼·영역 표시 조건 평가
        scwin.init_entryDefaults(); // 7) loadTp 기본값 충전
        scwin.init_sessionFill(); // 8) 세션 사용자 토큰 치환
        await scwin.init_pageBody(); // 9) 신규/조회 분기 본문 초기화
    } catch (e) {
        $c.exception.handleError(e, {
            context: 'jldfil59410.onpageload'
        });
    }
};

// 진입 파라미터 기본값 (회신표 entry_defaults — 전달분 우선). 진입점이 부르는 초기화 단계.
/**
 * @method
 * @name init_entryDefaults
 * @description 진입 파라미터 loadTp 기본값 충전 — 전달 파라미터와 dma_pageContext 값이 모두 비어 있을 때만 "0"(신규 작성)을 설정한다.
 * @returns {void}
 * @hidden N
 * @example scwin.init_entryDefaults();
 */
scwin.init_entryDefaults = function() {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || typeof pc.get !== 'function') {
        console.warn('[sdd] entry_defaults 대상 부재: dma_pageContext');
    } else if (($c.data.getParameter('loadTp') == null || $c.data.getParameter('loadTp') === '') && (pc.get('loadTp') == null || pc.get('loadTp') === '')) {
        pc.set('loadTp', "0");
    }
};

// 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님). 진입점 선두 단계.
/**
 * @method
 * @name init_nowVars
 * @description dma_pageContext.today 가 비어 있으면 서버 현재일(yyyyMMdd)로 충전한다.
 * @returns {void}
 * @hidden N
 * @example scwin.init_nowVars();
 */
scwin.init_nowVars = function() {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) {
        return;
    }
    if (!pc.get("today")) {
        pc.set("today", $c.date.getServerDateTime("yyyyMMdd"));
    }
};

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name init_attrReals
 * @description txa_remk 의 label 속성을 dma_detailData.remk 값으로 동적 렌더한다(공용 $c.util.applyAttrReals).
 * @returns {void}
 * @hidden N
 * @example scwin.init_attrReals();
 */
scwin.init_attrReals = function() {
    const attrReals = [{
        childId: "txa_remk",
        attr: "label",
        fn: function() {
            return String($c.data.readValue("dma_detailData", "remk", {
                silent: true
            }));
        }
    }];
    $c.util.applyAttrReals(attrReals);
};

// 런타임 분기 평가 — 공용 $c.util.evalConds (화면은 조건 바인딩 목록만 보유)
// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name init_conds
 * @description 처리상태(procsStatCd)·평가진행상태(skilValuProgStatCd)·진입유형(loadTp)에 따라 결과통보일 영역과 철회/삭제/수정/저장 버튼의 표시 조건을 평가한다(공용 $c.util.evalConds).
 * @returns {void}
 * @hidden N
 * @example scwin.init_conds();
 */
scwin.init_conds = function() {
    const readLoadTp = function() {
        return $c.data.readValue("dma_pageContext", "loadTp", {
            ctx: true,
            label: "loadTp"
        });
    };
    const readDetail = function(key) {
        return $c.data.readValue("dma_detailData", key, {
            label: "detailData." + key
        });
    };
    const binds = [{
        id: "if_rsltNotiDd",
        fn: function() {
            return readDetail("rsltNotiDd") !== '';
        }
    }, {
        id: "if_procsStatCd",
        fn: function() {
            return readLoadTp() !== '0' && readDetail("procsStatCd") !== '30';
        }
    }, {
        id: "btn_RetrRequest",
        fn: function() {
            if (readLoadTp() === '0') {
                return false;
            }
            const procsStatCd = readDetail("procsStatCd");
            if (!(procsStatCd !== '30' && procsStatCd !== '11')) {
                return false;
            }
            const skilValuProgStatCd = readDetail("skilValuProgStatCd");
            return skilValuProgStatCd !== '05' && skilValuProgStatCd !== '04';
        }
    }, {
        id: "btn_Delete",
        fn: function() {
            return readDetail("procsStatCd") === '30';
        }
    }, {
        id: "btn_Register_2",
        fn: function() {
            const procsStatCd = readDetail("procsStatCd");
            return procsStatCd === '30' || procsStatCd === '35' || procsStatCd === '37';
        }
    }, {
        id: "btn_Register",
        fn: function() {
            return readLoadTp() === '0';
        }
    }];
    $c.util.evalConds(binds);
};

// 제너레이터 채움 — 진입점(onpageload)에서 순차 실행. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name init_fillGen
 * @description 기타서류 첨부목록(dlt_attachList14)을 제너레이터(c_foreach_449)에 채운다 — 행별 btn_DownloadFile_8 에 첨부파일명을 설정하며, 이미 채워진 제너레이터는 건너뛴다(멱등).
 * @returns {void}
 * @hidden N
 * @example scwin.init_fillGen();
 */
scwin.init_fillGen = function() {
    const genFills = [{
        genId: "c_foreach_449",
        entity: "dlt_attachList14",
        countIds: [],
        cells: [{
            childId: "btn_DownloadFile_8",
            fn: function(read, idx) {
                return String(read("attachFileNm"));
            }
        }]
    }];
    for (let g = 0; g < genFills.length; g++) {
        const f = genFills[g];
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) {
            continue;
        }
        const n = ds.getTotalRow();
        if (!n) {
            continue;
        }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        if (gen.getLength && gen.getLength() > 0) {
            continue;
        }
        let rowIdx = 0;
        const readCell = function(col) {
            const v = ds.getCellData(rowIdx, col);
            return (v === undefined || v === null) ? '' : v;
        };
        for (let i = 0; i < n; i++) {
            rowIdx = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) {
                    continue;
                }
                ch.setValue(f.cells[c].fn(readCell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) {
                    cn.setValue(String(i + 1));
                }
            }
        }
    }
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name init_rowCopy
 * @description dataCollection 값을 표시 컴포넌트로 복사한다 — loadTp, 법인등록번호 앞/뒷자리 분할, 첨부파일명(신청서·부속서류·기타서류) 다운로드 버튼 라벨, 결과통보일(공용 $c.data.copyRows).
 * @returns {void}
 * @hidden N
 * @example scwin.init_rowCopy();
 */
scwin.init_rowCopy = function() {
    const rowCopies = [{
            childId: "ipt_loadTp",
            fn: function() {
                return String(String($c.data.readValue("dma_pageContext", "loadTp", {
                    silent: true
                })));
            }
        },
        {
            childId: "ipt_corpRegNo1",
            fn: function() {
                return String(String(String($c.data.readValue("dma_detailData", "corpRegNo", {
                    silent: true
                }))).substring(0, 6));
            }
        },
        {
            childId: "ipt_corpRegNo2",
            fn: function() {
                return String(String(String($c.data.readValue("dma_detailData", "corpRegNo", {
                    silent: true
                }))).substring(6, 13));
            }
        },
        {
            childId: "btn_DownloadFile",
            fn: function() {
                return String($c.data.readValue("dlt_attachList01", "attachFileNm", {
                    row: 0,
                    silent: true
                }));
            }
        },
        {
            childId: "btn_DownloadFile_2",
            fn: function() {
                return String($c.data.readValue("dlt_attachList02", "attachFileNm", {
                    row: 0,
                    silent: true
                }));
            }
        },
        {
            childId: "btn_DownloadFile_3",
            fn: function() {
                return String($c.data.readValue("dlt_attachList02", "attachFileNm", {
                    row: 1,
                    silent: true
                }));
            }
        },
        {
            childId: "btn_DownloadFile_4",
            fn: function() {
                return String($c.data.readValue("dlt_attachList02", "attachFileNm", {
                    row: 2,
                    silent: true
                }));
            }
        },
        {
            childId: "btn_DownloadFile_5",
            fn: function() {
                return String($c.data.readValue("dlt_attachList13", "attachFileNm", {
                    row: 0,
                    silent: true
                }));
            }
        },
        {
            childId: "btn_DownloadFile_6",
            fn: function() {
                return String($c.data.readValue("dlt_attachList13", "attachFileNm", {
                    row: 1,
                    silent: true
                }));
            }
        },
        {
            childId: "btn_DownloadFile_7",
            fn: function() {
                return String($c.data.readValue("dlt_attachList13", "attachFileNm", {
                    row: 2,
                    silent: true
                }));
            }
        },
        {
            childId: "__rb0",
            fn: function() {
                return String(String($c.data.readValue("dma_detailData", "rsltNotiDd", {
                    silent: true
                })));
            }
        },
        {
            childId: "__rb1",
            fn: function() {
                return " " + String(String($c.data.readValue("dma_detailData", "rsltNotiDd", {
                    silent: true
                })));
            }
        }
    ];
    $c.data.copyRows(rowCopies);
};

/**
 * @method
 * @name initExcInstCd
 * @description 제척기관 선택 콤보(slc_listExcInstCd0)를 첫 항목으로 되돌린다 — 콤보가 단일이면 그대로, 복수(배열)면 첫 번째 요소를 대상으로 selectedIndex 를 0 으로 설정한다.
 * @returns {void}
 * @hidden N
 * @example scwin.initExcInstCd();
 */
scwin.initExcInstCd = function() {
    let objArr = null;
    const excInstCd = $c.util.getComponent('slc_listExcInstCd0');
    if (scwin.selExcInst === 1) {
        objArr = excInstCd;
    } else {
        objArr = excInstCd[0];
    }
    objArr.selectedIndex = 0;
};


/**
 * @method
 * @name init_pageBody
 * @description 신규/조회 분기 본문 초기화 — 신규(loadTp "0")면 배정신청일에 서버 현재일을 넣고 연장신청여부를 "N"으로 초기화하며, 조회면 업로드 결과 코드(uploadCode)에 따라 안내 후 setData 로 상세값을 복원한다.
 *              이어서 평가결과 요약표(valuRsltInfo1~6) 렌더와 form_search/chkNumber 입력 검사 이벤트를 바인딩한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.init_pageBody();
 */
scwin.init_pageBody = async function() {
    try {
        scwin.form = (document.insertForm || {
            elements: []
        });
        if (scwin.loadTp === "0") {
            $c.util.getComponent("ipt_AssgnApplDd").setValue($c.date.getServerDateTime('yyyyMMdd'));
            $c.util.getComponent("rd_extnApplYn").setValue("N");
            await scwin.activeExtnYn("N", false);
        } else {
            if (scwin.uploadCode === "0") {

            } else {
                if (scwin.uploadCode === "1") {
                    await $c.win.alert('해당유형의 파일은 업로드할 수 없습니다.');
                } else {
                    if (scwin.uploadCode === "2") {
                        await $c.win.alert('업로드 하려는 파일의 크기가 허용한도를 초과 하였습니다.');
                    }
                }
            }
            await scwin.setData();
        }
        scwin.setLeadcomVars();
        scwin.setSpecyValuInsts();
        let valuRslt = "";
        let innerStr = "";
        valuRslt = $c.util.getComponent('valuRsltInfo1');
        innerStr = "";
        innerStr += "<th>평가상태</th>";
        innerStr += "<td >" + $c.data.readValue("dma_detailData", "skil_valu_prog_stat_nm", {
            silent: true
        }) + "</td>";
        innerStr += "<th>처리상태</th>";
        innerStr += "<td>" + $c.data.readValue("dma_detailData", "list_procs_stat_nm", {
            silent: true
        }) + "</td>";
        valuRslt.innerHTML = innerStr;
        valuRslt = $c.util.getComponent('valuRsltInfo2');
        innerStr = "";
        innerStr += "<th>배정일</th>";
        innerStr += "<td>" + $c.data.readValue("dma_detailData", "skil_valu_assgn_dd", {
            silent: true
        }) + "</td>";
        innerStr += "<th>철회일</th>";
        innerStr += "<td>" + $c.data.readValue("dma_detailData", "assgn_suspn_dd", {
            silent: true
        }) + "</td>";
        valuRslt.innerHTML = innerStr;
        valuRslt = $c.util.getComponent('valuRsltInfo3');
        innerStr = "";
        innerStr += "<th>평가기관1</th>";
        innerStr += "<td>" + $c.data.readValue("dma_detailData", "skil_valu_inst_nm1", {
            silent: true
        }) + "</td>";
        innerStr += "<th>평가기관2</th>";
        innerStr += "<td>" + $c.data.readValue("dma_detailData", "skil_valu_inst_nm2", {
            silent: true
        }) + "</td>";
        valuRslt.innerHTML = innerStr;
        valuRslt = $c.util.getComponent('valuRsltInfo4');
        innerStr = "";
        innerStr += "<th>평가기관1 담당자</th>";
        innerStr += "<td>" + $c.data.readValue("dma_detailData", "valu_inst_chrg_nm", {
            silent: true
        }) + "</td>";
        innerStr += "<th>평가기관2 담당자</th>";
        innerStr += "<td>" + $c.data.readValue("dma_detailData", "valu_inst_chrg_nm2", {
            silent: true
        }) + "</td>";
        valuRslt.innerHTML = innerStr;
        valuRslt = $c.util.getComponent('valuRsltInfo5');
        innerStr = "";
        innerStr += "<th>평가기관1 연락처</th>";
        innerStr += "<td>" + $c.data.readValue("dma_detailData", "valu_inst_tel_no", {
            silent: true
        }) + "</td>";
        innerStr += "<th>평가기관2 연락처</th>";
        innerStr += "<td>" + $c.data.readValue("dma_detailData", "valu_inst_tel_no2", {
            silent: true
        }) + "</td>";
        valuRslt.innerHTML = innerStr;
        valuRslt = $c.util.getComponent('txt_valuRsltInfo6');
        innerStr = "";
        innerStr += "<th>평가기관1 이메일</th>";
        innerStr += "<td>" + $c.data.readValue("dma_detailData", "valu_inst_email", {
            silent: true
        }) + "</td>";
        innerStr += "<th>평가기관2 이메일</th>";
        innerStr += "<td>" + $c.data.readValue("dma_detailData", "valu_inst_email2", {
            silent: true
        }) + "</td>";
        valuRslt.innerHTML = innerStr;
        // 규칙 19 — jQuery 클래스 일괄 바인딩 제거: form_search/chkNumber 클래스를 가진 컴포넌트가
        // 전환 마크업에 없어(실측 0건) ev:onblur/ev:onkeyup 속성 이관 대상이 없다.
        // 원본 JSP 잔재 클래스가 배포 DOM(파일 컨트롤 등)에 존재할 가능성에 대비해 표준 DOM API 로 동등 바인딩한다.
        document.querySelectorAll(".form_search").forEach(function(el) {
            el.addEventListener("focusout", function(e) {
                if ($c.cm.fn_IsExceedMaxLen(this)) {
                    e.preventDefault();
                    e.stopPropagation();
                }
            });
        });
        document.querySelectorAll(".chkNumber").forEach(function(el) {
            el.addEventListener("keyup", function(e) {
                if ($c.cm.fn_ChkNumber2(this)) {
                    e.preventDefault();
                    e.stopPropagation();
                }
            });
        });

    } catch (_ex) {
        await $c.exception.handleError(_ex, {
            context: 'jldfil59410.onpageload'
        });
    }
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)
/**
 * @method
 * @name init_sessionFill
 * @description 세션 사용자 정보(usrId)로 화면 내 EL 토큰(session.user.*)을 치환한다 — 렌더 루트의 텍스트 노드 전체와 input/textarea 의 value 를 순회 치환한다.
 * @returns {void}
 * @hidden N
 * @example scwin.init_sessionFill();
 */
scwin.init_sessionFill = function() {
    const names = ["usrId"];

    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v;
            try {
                v = $c.session.getUserInfo(names[i]);
            } catch (_e) {
                $c.exception.handleError(_e, {
                    notify: 'none',
                    context: 'jldfil59410'
                });
                v = undefined;
            }
            if (v === undefined || v === null || v === '') {
                continue;
            }
            const token = '${session.user.' + names[i] + '}';
            const frameRender = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document);
            let renderRoot = frameRender;
            renderRoot = renderRoot.body || renderRoot;
            const doc = renderRoot.ownerDocument || renderRoot;
            const w = doc.createTreeWalker(renderRoot, NodeFilter.SHOW_TEXT);
            let n;
            while ((n = w.nextNode())) {
                if (n.nodeValue.indexOf(token) >= 0) {
                    n.nodeValue = n.nodeValue.split(token).join(v);
                }
            }
            const ins = frameRender.querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) {
                if (ins[j].value && ins[j].value.indexOf(token) >= 0) {
                    ins[j].value = ins[j].value.split(token).join(v);
                }
            }
        }
    }
    fill();
};

// 화면 전환 파라미터 수신 — 공용 $c.data.recvParamData (§106, 이름 고정 "paramData"; 실패 표출은 gcc 함수 몫). onpageload 합성 단계.
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터를 dma_pageContext 로 수신한다(공용 $c.data.recvParamData, 이름 고정 "paramData").
 * @returns {void}
 * @hidden N
 * @example scwin.init_recvParam();
 */
scwin.init_recvParam = function() {
    $c.data.recvParamData('dma_pageContext');
};

// 파일 컨트롤 해석 헬퍼 — 아래 scwin.fileTpCd01~upd_fileTpCd13_3 로드 시점 초기화가 사용하므로 이 위치(사용부 상단)에 정의한다.
/**
 * @method
 * @name findFileControl
 * @description 파일 업로드 컨트롤 DOM 을 해석한다 — 전역 __krxFileControl 헬퍼가 있으면 위임하고, 없으면 화면 프레임 렌더 루트(부재 시 document)에서 id 로 조회한다.
 * @param {String} id 파일 컨트롤 요소 id
 * @returns {Object} 파일 컨트롤 DOM 요소(미해결 시 null)
 * @hidden N
 * @example scwin.findFileControl('fileTpCd01');
 */
scwin.findFileControl = function(id) {
    if (typeof __krxFileControl === 'function') {
        return __krxFileControl(id);
    }
    const root = (typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document;
    return root.querySelector('[id="' + id + '"]');
};

scwin.fileTpCd01 = scwin.findFileControl('fileTpCd01');

scwin.upd_fileTpCd02 = scwin.findFileControl('upd_fileTpCd02');

scwin.upd_fileTpCd02_2 = scwin.findFileControl('upd_fileTpCd02_2');

scwin.upd_fileTpCd02_3 = scwin.findFileControl('upd_fileTpCd02_3');

scwin.upd_fileTpCd13 = scwin.findFileControl('upd_fileTpCd13');

scwin.upd_fileTpCd13_2 = scwin.findFileControl('upd_fileTpCd13_2');

scwin.upd_fileTpCd13_3 = scwin.findFileControl('upd_fileTpCd13_3');

// 페이지 파라미터 문자열 해석 헬퍼 — 아래 scwin.loadTp/returnVal 로드 시점 초기화가 사용하므로 이 위치(사용부 상단)에 정의한다.
/**
 * @method
 * @name readPageParam
 * @description dma_pageContext 파라미터를 문자열로 읽는다 — null/undefined 는 빈 문자열로, 미치환 EL 토큰이 남은 값('$'+'{' 포함)도 빈 문자열로 간주한다.
 * @param {String} key 파라미터 키
 * @returns {String} 해석된 파라미터 문자열
 * @hidden N
 * @example const loadTp = scwin.readPageParam("loadTp");
 */
scwin.readPageParam = function(key) {
    const raw = $c.data.readValue("dma_pageContext", key, {
        ctx: true,
        soft: true,
        label: key
    });
    const str = String(raw == null ? '' : raw);
    return str.indexOf('$' + '{') >= 0 ? '' : str;
};

scwin.loadTp = scwin.readPageParam("loadTp");

scwin.returnVal = scwin.readPageParam("returnVal");


