/**
 * @method
 * @name tx_fn_Delete
 * @description 배정신청 삭제 서브미션 — dma_DeleteReq 를 specyValuAppl.do 로 전송하고, 실패 응답이면 서버 메시지를 알린 뒤 응답 객체를 반환한다.
 * @returns {Object} executeDynamic 응답 객체(resObj, 통신 예외 시 null)
 * @hidden N
 * @example const res = await scwin.tx_fn_Delete();
 */
scwin.tx_fn_Delete = async function() {
    const sbmOptions = {
        id: "tx_fn_Delete",
        method: "post",
