/**
 * @method
 * @name setLeadcomVars
 * @description 주관사 목록 복원(as-is JSP 스크립틀릿 변환 산출) — entity.leadcom_mbr_no 를 읽어 leadcomList 항목 수만큼 주관사 행을 추가하고 콤보(slc_listAgnccomMbrNo0)에 값을 설정한다.
 * @returns {void}
 * @hidden N
 * @example scwin.setLeadcomVars();
 */
scwin.setLeadcomVars = function() {
    const leadcomList = new Array();
    leadcomList[$];
    status.index;
    const leadcomMbrNo = $c.data.readValue("entity", "leadcom_mbr_no", {
        label: "entity.leadcom_mbr_no"
    });
    (String(leadcomMbrNo == null ? '' : leadcomMbrNo).indexOf('$' + '{') >= 0 ? '' : String(leadcomMbrNo == null ? '' : leadcomMbrNo));
    for (let i = 0; i < leadcomList.length; i++) {
        if (i !== 0) {
            scwin.addListAgnccomMbr(i - 1);
        }
        if (i === 0) {
            $c.util.getComponent("slc_listAgnccomMbrNo0").setValue(leadcomList[i]);
        } else {
            $c.util.getComponent('slc_listAgnccomMbrNo0')[i].value = leadcomList[i];
        }
    }
};


