/**
 * @method
 * @name setData
 * @description 조회 진입 시 상세값 복원 — 사업자등록번호 3분할 표시, 1사 신청 사유 검사, 평가기관2 일자 비활성(1사 선택 시), 연장신청여부·기술사업유형 반영, 비고 바이트 수 갱신, 전화·팩스·이메일 분할 입력 충전을 수행한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.setData();
 */
scwin.setData = async function() {
    const bzRegNo = $c.util.getComponent('ipt_bzRegNo').getValue();
    if (bzRegNo.length === 10) {
        $c.util.getComponent("ipt_bzRegNo1").setValue(bzRegNo.substring(0, 3));
        $c.util.getComponent("ipt_bzRegNo2").setValue(bzRegNo.substring(3, 5));
        $c.util.getComponent("ipt_bzRegNo3").setValue(bzRegNo.substring(5, 10));
    }
    const obj = $c.util.getComponent('slc_onecomApplRsnCd');
    await scwin.fn_chkOnecomApplRsnCd(obj);
    if (($c.util.getComponent('rd_valuInstApplCnt').getValue() === '1')) {
        $c.util.getComponent('cal_valuStrtDd2').setDisabled(true);
        $c.util.getComponent('cal_valuSchdlEndDd2').setDisabled(true);
        $c.util.getComponent('cal_extnExpddDd2').setDisabled(true);
    }
    await scwin.activeExtnYn($c.util.getComponent('rd_extnApplYn').getValue(), false);
    scwin.checkSkilBzTpCd($c.util.getComponent('rd_skilBzTpCd').getValue());
    $c.cm.fn_CheckByte($c.util.getComponent('txa_remk'), '2000', 'byteCnt');
    $c.cm.fn_SetPhoneValue('telNo', $c.util.getComponent('ipt_telNo').getValue(), scwin.form);
    $c.cm.fn_SetPhoneValue('faxNo', $c.util.getComponent('ipt_faxNo').getValue(), scwin.form);
    $c.cm.fn_SetPhoneValue('apctTelNo', $c.util.getComponent('ipt_apctTelNo').getValue(), scwin.form);
    $c.cm.fn_SetEmaileValue('apctEmail', $c.util.getComponent('ipt_apctEmail').getValue(), scwin.form);
};


