/**
 * @method
 * @name activeExtnYn
 * @description 연장신청여부에 따른 연장기일 입력 제어 — "N"이면 연장기일 1·2 를 비활성·초기화하고, "Y"면 연장기일1(2사 신청 시 연장기일2 포함)을 활성화하며 msgYn 이 참이면 안내 메시지를 띄운다.
 * @param {String} val 연장신청여부 값("Y"/"N")
 * @param {Boolean} msgYn 활성화 시 안내 메시지 표시 여부
 * @returns {void}
 * @hidden N
 * @example await scwin.activeExtnYn("N", false);
 */
scwin.activeExtnYn = async function(val, msgYn) {
    const dd1 = $c.util.getComponent("cal_extnExpddDd");
    const dd2 = $c.util.getComponent("cal_extnExpddDd2");
    if (val === "N") {
        dd1.setDisabled(true);
        dd2.setDisabled(true);
        dd1.setValue("");
        dd2.setValue("");
    } else {
        dd1.setDisabled(false);
        if (($c.util.getComponent('rd_valuInstApplCnt').getValue() === '2')) {
            dd2.setDisabled(false);
        }
        if (msgYn) {
            await $c.win.alert("연장신청시 연장기일 입력과 기타서류(연장공문)를 첨부하세요.");
        }
    }
};


/**
 * @method
 * @name checkSkilBzTpCd
 * @description 기술사업유형에 따른 분류 콤보 제어 — "02"(기타)면 산업/기술분류 콤보 4종을 비활성·초기화하고, 그 외에는 활성화한다.
 * @param {String} val 기술사업유형 코드
 * @returns {void}
 * @hidden N
 * @example scwin.checkSkilBzTpCd("02");
 */
scwin.checkSkilBzTpCd = function(val) {
    if (val === "02") {
        $c.util.getComponent('slc_specyValuIndClssCd').setDisabled(true);
        $c.util.getComponent('slc_specyValuIndClssCd2').setDisabled(true);
        $c.util.getComponent('slc_specyValuSkilClssCd').setDisabled(true);
        $c.util.getComponent('slc_specyValuSkilClssCd2').setDisabled(true);
        $c.util.getComponent("slc_specyValuIndClssCd").setValue("");
        $c.util.getComponent("slc_specyValuIndClssCd2").setValue("");
        $c.util.getComponent("slc_specyValuSkilClssCd").setValue("");
        $c.util.getComponent("slc_specyValuSkilClssCd2").setValue("");
    } else {
        $c.util.getComponent('slc_specyValuIndClssCd').setDisabled(false);
        $c.util.getComponent('slc_specyValuIndClssCd2').setDisabled(false);
        $c.util.getComponent('slc_specyValuSkilClssCd').setDisabled(false);
        $c.util.getComponent('slc_specyValuSkilClssCd2').setDisabled(false);
    }
};


/**
 * @method
 * @name checkMbrNoInfo
 * @description 주관사/제척기관 선택 필수 검사 — 대상 컴포넌트 값이 비어 있으면 항목명을 포함한 알림 후 포커스를 옮기고 false 를 반환한다.
 * @param {Object} obj 검사 대상 컴포넌트(select/text)
 * @param {String} strMsg 알림에 표시할 항목명
 * @returns {Boolean} 검사 통과 여부
 * @hidden N
 * @example if (!await scwin.checkMbrNoInfo(comp, "주관사")) { return false; }
 */
scwin.checkMbrNoInfo = async function(obj, strMsg) {
    let strVal = null;
    if (obj.type === "select-one") {
        strVal = obj.getValue();
    } else {
        if (obj.type === "text") {
            strVal = obj.getValue();
        }
    }
    if (strVal === "") {
        await $c.win.alert("[" + strMsg + "] 항목 선택은 필수 입니다.");
        obj.focus();
        return false;
    }
    return true;
};


/**
 * @method
 * @name fn_chkDuplicateMbrNo
 * @description 주관사 중복 선택 검사 — 주관사 행이 2개 이상일 때 다른 행과 같은 값을 고르면 알림 후 값을 비우고 false 를 반환한다.
 * @param {Object} chkObj 변경된 주관사 콤보 요소
 * @returns {Boolean} 검사 통과 여부
 * @hidden N
 * @example await scwin.fn_chkDuplicateMbrNo(chkObj);
 */
scwin.fn_chkDuplicateMbrNo = async function(chkObj) {
    if (scwin.agnccomMbr > 1) {
        const mbrNoArr = $c.util.getComponent('slc_listAgnccomMbrNo0');
        let chkDupFlag = false;
        for (let i = 0; i < scwin.agnccomMbr; i++) {
            if (chkObj !== mbrNoArr[i] && chkObj.value === mbrNoArr[i].value) {
                chkDupFlag = true;
                break;
            }
        }
        if (chkDupFlag) {
            await $c.win.alert("주관사은 중복하여 선택할 수 없습니다.");
            chkObj.value = "";
            chkObj.focus();
            return false;
        }
    }
    return true;
};


