        gen.insertChild();
    }
};


/**
 * @method
 * @name fn_chkDuplicateExcInstCd
 * @description 제척기관 선택 검사 — 제척기관 행 간 중복 선택과 평가기관(skil_valu_inst_cd1/2)으로 기등록된 기관 선택을 차단하고, 위반 시 알림 후 false 를 반환한다.
 * @param {Object} chkObj 변경된 제척기관 콤보 요소
 * @returns {Boolean} 검사 통과 여부
 * @hidden N
 * @example await scwin.fn_chkDuplicateExcInstCd(chkObj);
 */
scwin.fn_chkDuplicateExcInstCd = async function(chkObj) {
    if (scwin.selExcInst > 1) {
        const cdArr = $c.util.getComponent('slc_listExcInstCd0');
        let chkDupFlag = false;
        for (let i = 0; i < scwin.selExcInst; i++) {
            if (chkObj !== cdArr[i] && chkObj.value === cdArr[i].value) {
                chkDupFlag = true;
                break;
            }
        }
        if (chkDupFlag) {
            await $c.win.alert("제척기관은 중복하여 선택할 수 없습니다.");
            chkObj.selectedIndex = 0;
            chkObj.value = "";
            chkObj.focus();
            return false;
        }
    }
    const instCd1 = '' + $c.data.readValue("dma_detailData", "skil_valu_inst_cd1", {
        silent: true
    }) + '';
    const instCd2 = '' + $c.data.readValue("dma_detailData", "skil_valu_inst_cd2", {
        silent: true
    }) + '';
    if (chkObj.value === instCd1 || chkObj.value === instCd2) {
        await $c.win.alert("평가기관에 등록된 기간은 선택할 수 없습니다.");
        chkObj.selectedIndex = 0;
        return false;
    }
    return true;
};


