/**
 * @method
 * @name fn_chkValuInstApplCnt
 * @description 평가기관 신청수 변경 처리 — 1사 신청 사유 콤보를 활성화해 재검사하고, 신청수(1사/2사)에 따라 평가기관2 일자 입력의 활성 상태를 setValuInstInfo 로 전환한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.fn_chkValuInstApplCnt();
 */
scwin.fn_chkValuInstApplCnt = async function() {
    const obj = $c.util.getComponent('slc_onecomApplRsnCd');
    const viewDiv = $c.util.getComponent("rsnNmDiv");
    obj.setDisabled(false);
    await scwin.fn_chkOnecomApplRsnCd(obj);
    if (($c.util.getComponent('rd_valuInstApplCnt').getValue() === '2')) {
        scwin.setValuInstInfo(false);
    } else {
        if (($c.util.getComponent('rd_valuInstApplCnt').getValue() === '1')) {
            scwin.setValuInstInfo(true);
        }
    }
};


/**
 * @method
 * @name setValuInstInfo
 * @description 평가기관2 일자 입력 제어 — 평가개시일2·평가예정종료일2 의 활성 상태를 flag 로 전환하며 값을 초기화하고, 연장신청 "Y" 상태면 연장기일2 도 동일하게 처리한다.
 * @param {Boolean} flag 비활성 여부(true = 비활성)
 * @returns {void}
 * @hidden N
 * @example scwin.setValuInstInfo(true);
 */
scwin.setValuInstInfo = function(flag) {
    $c.util.getComponent('cal_valuStrtDd2').setDisabled(flag);
    $c.util.getComponent("cal_valuStrtDd2").setValue("");
    $c.util.getComponent('cal_valuSchdlEndDd2').setDisabled(flag);
    $c.util.getComponent("cal_valuSchdlEndDd2").setValue("");
    if (($c.util.getComponent('rd_extnApplYn').getValue() === 'Y')) {
        $c.util.getComponent('cal_extnExpddDd2').setDisabled(flag);
        $c.util.getComponent("cal_extnExpddDd2").setValue("");
    }
};


/**
 * @method
 * @name fn_chkOnecomApplRsnCd
 * @description 1사 신청 사유 검사 — 사유 미선택이면 직접입력 영역(rsnNmDiv)을 표시하고, 선택 시 영역을 숨기며 입력값을 초기화한다. 신청수가 1사인데 "99"(해당없음)를 고르면 알림 후 선택을 되돌리고 false 를 반환한다.
 * @param {Object} obj 1사 신청 사유 콤보 컴포넌트
 * @returns {Boolean} 위반 시 false, 그 외 undefined
 * @hidden N
 * @example await scwin.fn_chkOnecomApplRsnCd(obj);
 */
scwin.fn_chkOnecomApplRsnCd = async function(obj) {
    const viewDiv = $c.util.getComponent("rsnNmDiv");
    const selVal = obj.getValue();
    if (selVal === "") {
        if (!viewDiv) {
            console.warn('[sdd] 표시 전환 대상 미해결: viewDiv');
        } else if (("block") === 'none') {
            if (viewDiv.hide) {
                viewDiv.hide();
            }
        } else {
            if (viewDiv.show) {
                viewDiv.show();
            }
        }
    } else {
        if (!viewDiv) {
            console.warn('[sdd] 표시 전환 대상 미해결: viewDiv');
        } else if (("none") === 'none') {
            if (viewDiv.hide) {
                viewDiv.hide();
            }
        } else {
            if (viewDiv.show) {
                viewDiv.show();
            }
        }
        $c.util.getComponent("ipt_onecomApplRsnNm").setValue("");
    }
    if (($c.util.getComponent('rd_valuInstApplCnt').getValue() === '1')) {
        if (selVal === "99") {
            await $c.win.alert("평가기관 신청수가 1사인 경우에는 해당없음을 선택할 수 없습니다.");
            obj.setSelectedIndex(0);
            if (!viewDiv) {
                console.warn('[sdd] 표시 전환 대상 미해결: viewDiv');
            } else if (("block") === 'none') {
                if (viewDiv.hide) {
                    viewDiv.hide();
                }
            } else {
                if (viewDiv.show) {
                    viewDiv.show();
                }
            }
            return false;
        }
    }
};


/**
 * @method
 * @name fn_chkFornComYn
 * @description 외국법인여부 처리 — "Y"면 안내 후 법인등록번호를 '0' 문자열로 채우고, "N"이면 법인등록번호 입력을 초기화한다.
 * @param {Object} obj 외국법인여부 콤보 컴포넌트
 * @returns {void}
 * @hidden N
 * @example await scwin.fn_chkFornComYn(obj);
 */
scwin.fn_chkFornComYn = async function(obj) {
    if (obj.getValue() === "Y") {
        await $c.win.alert("법인등록번호를 '0' 값으로 입력합니다");
        $c.util.getComponent("ipt_corpRegNo1").setValue("000000");
        $c.util.getComponent("ipt_corpRegNo2").setValue("0000000");
    } else {
        $c.util.getComponent("ipt_corpRegNo1").setValue("");
        $c.util.getComponent("ipt_corpRegNo2").setValue("");
    }
};


/**
 * @method
 * @name fn_checkCorpRegNo
 * @description 법인등록번호 검사 — 앞/뒷자리 필수 검증(validateDataCollect) 후 결합 자릿수(13자리)를 확인하고, 잘못되면 알림 후 false 를 반환한다.
 * @param {String} corpRegNo 결합된 법인등록번호(13자리)
 * @returns {Boolean} 검사 통과 여부
 * @hidden N
 * @example if (!await scwin.fn_checkCorpRegNo(corpRegNo)) { return false; }
 */
scwin.fn_checkCorpRegNo = async function(corpRegNo) {
    const vFields = {};
    vFields["ipt_corpRegNo1"] = {
        required: true
    };
    vFields["ipt_corpRegNo2"] = {
        required: true
    };
    const result = await $c.validate.validateDataCollect($c.util.getComponent("form_5"), {
        validateType: 'alert',
        checkType: 'single',
        focus: true,
        fields: vFields
    });
    if (!result) {
        return false;
    }
    if (corpRegNo.length !== 13) {
        await $c.win.alert('법인등록번호가 잘못되었습니다');
        return false;
    }
    if ((corpRegNo + 0) === 0) {
        return true;
    }
    return true;
};


/**
 * @method
 * @name fn_Register
 * @description 저장/수정 등록 처리 — checkForm 검증 통과 시 dma_RegisterReq 에 법인·사업자등록번호, 우편번호·주소, 추가제척기관 여부, 처리 방식(method)을 설정하고 확인 후 목록 화면(jldfil59400)으로 이동한다.
 * @param {String} val 처리 방식("write" 저장 / "edit" 수정)
 * @param {String} srtMsg 확인 메시지에 표시할 동작명
 * @returns {void}
 * @hidden N
 * @example await scwin.fn_Register('write', '저장');
 */
scwin.fn_Register = async function(val, srtMsg) {
    const frm = (document.insertForm || {
        elements: []
    });
    if (await scwin.checkForm(frm)) {
        const registerReq = $c.util.getComponent("dma_RegisterReq");
        registerReq.set("corpRegNo", $c.util.getComponent('ipt_corpRegNo1').getValue() + $c.util.getComponent('ipt_corpRegNo2').getValue());
        registerReq.set("bzRegNo", $c.util.getComponent('ipt_bzRegNo1').getValue() + $c.util.getComponent('ipt_bzRegNo2').getValue() + $c.util.getComponent('ipt_bzRegNo3').getValue());
        registerReq.set("Zipcd", $c.util.getComponent('ipt_Zipcd').getValue());
        registerReq.set("ComAddr", registerReq.get("ComAddr"));
        registerReq.set("AssgnApplDd", registerReq.get("AssgnApplDd"));
        if (($c.util.getComponent('ipt_addExcInstNm').getValue() == null ? '' : String($c.util.getComponent('ipt_addExcInstNm').getValue())) === '') {
            registerReq.set("addExcInstYn", "N");
        } else {
            registerReq.set("addExcInstYn", "Y");
        }
        if (frm.skilBzTpCd[1].checked) {
            scwin.checkSkilBzTpCd("02");
        }
        frm.action = "/listInvstg/specyValuAppl.do";
        registerReq.set("method", val);
        if (await $c.win.confirm(srtMsg + '하시겠습니까?')) {
            $c.win.moveUrl("/jldfil59400/jldfil59400.xml", {
                "zipcd": $c.util.getComponent('ipt_Zipcd').getValue(),
                "comAddr": registerReq.get("ComAddr"),
                "assgnApplDd": registerReq.get("AssgnApplDd"),
                "addExcInstYn": "N",
                "method": val
            });
        }
    }
};


