/**
 * @method
 * @name delAttachFile
 * @description 첨부파일 삭제 표시 전환 — 기존 첨부 표시 영역(fileTpCd+번호+순번)을 숨기고, 편집 영역(Edit-*)에 재업로드 file input 과 삭제 대상 hidden(delAttachFileNo)을 렌더해 표시한다.
 * @param {String} fileNo 파일유형 번호("01"/"02"/"13")
 * @param {String} fileSeq 파일 순번
 * @param {String} strTitle 재업로드 입력 title 로 쓸 서류명
 * @returns {void}
 * @hidden N
 * @example scwin.delAttachFile('01', '1', '신청서 첨부');
 */
scwin.delAttachFile = function(fileNo, fileSeq, strTitle) {
    const viewDiv = $c.util.getComponent("fileTpCd" + fileNo + fileSeq);
    viewDiv.style.display = "none";
    const editDiv = $c.util.getComponent("Edit-fileTpCd" + fileNo + fileSeq);
    let txt = "";
    txt += "	<input type='file' name='fileTpCd" + fileNo + "[" + (fileSeq - 1) + "]' title='" + strTitle + "' class='w500' size='70'/>";
    txt += "  <br/><span style='color:#52abcc'>* 첨부파일 수정하는 경우 하단의 '수정' 버튼을 선택해야 합니다.</span> ";
    txt += "	<input type='hidden' name='delAttachFileNo' value='" + fileNo + fileSeq + "'/> ";
    editDiv.innerHTML = txt;
    editDiv.style.display = "block";
};


/**
 * @method
 * @name fn_chkUploadFile
 * @description 첨부파일 용량 검사 — 화면의 모든 file input 을 순회하며 chkSize(MB)를 초과한 파일이 있으면 파일명을 포함해 알린 뒤 true(차단)를 반환한다.
 * @param {String} chkSize 허용 최대 용량(MB)
 * @returns {Boolean} 초과 파일 존재 시 true, 그 외 undefined
 * @hidden N
 * @example if (await scwin.fn_chkUploadFile('20')) { return false; }
 */
scwin.fn_chkUploadFile = async function(chkSize) {
    // 규칙 19 — file input 은 파일 컨트롤(__krxFileControl) 내부·동적 렌더(delAttachFile) DOM 이라
    // 대응 WebSquare 컴포넌트가 없어 표준 DOM 조회로 전환한다.
    const all_files = document.querySelectorAll('input[type="file"]');
    let tmpFile = "";
    const chkSizeM = 20;
    let tmpFileSize = "";
    let tmpFileName = "";
    for (let i = 0; i < all_files.length; i++) {
        tmpFile = all_files[i].files[0];
        if (tmpFile != null && tmpFile !== '') {
            tmpFileSize = all_files[i].files[0].size;
            tmpFileSize = tmpFileSize / (1024 * 1024);
            tmpFileName = all_files[i].files[0].name;
            if (tmpFileSize > chkSize) {
                await $c.win.alert(tmpFileName + " 첨부파일의 사이즈가 " + chkSize + "MB을 넘으면 등록할 수 없습니다. 파일을 확인해주세요.");
                return true;
            }
        }
    }
};


/**
 * @method
 * @name fn_checkBzRegNo
 * @description 사업자등록번호 검증번호 검사 — 3분할 입력을 결합해 가중치(1·3·7·1·3·7·1·3·5) 검증합을 계산하고, 검증 실패 시 알림 후 false 를 반환한다(빈 값은 통과).
 * @returns {Boolean} 검사 통과 여부
 * @hidden N
 * @example if (!await scwin.fn_checkBzRegNo()) { return false; }
 */
scwin.fn_checkBzRegNo = async function() {
    const bzRegNo1 = $c.util.getComponent('ipt_bzRegNo1').getValue();
    const bzRegNo2 = $c.util.getComponent('ipt_bzRegNo2').getValue();
    const bzRegNo3 = $c.util.getComponent('ipt_bzRegNo3').getValue();
    const bzRegNo = bzRegNo1 + bzRegNo2 + bzRegNo3;
    if (bzRegNo.length > 0) {
        let subMode = 0;
        subMode += parseInt(bzRegNo.substring(0, 1));
        subMode += parseInt(bzRegNo.substring(1, 2)) * 3 % 10;
        subMode += parseInt(bzRegNo.substring(2, 3)) * 7 % 10;
        subMode += parseInt(bzRegNo.substring(3, 4)) * 1 % 10;
        subMode += parseInt(bzRegNo.substring(4, 5)) * 3 % 10;
        subMode += parseInt(bzRegNo.substring(5, 6)) * 7 % 10;
        subMode += parseInt(bzRegNo.substring(6, 7)) * 1 % 10;
        subMode += parseInt(bzRegNo.substring(7, 8)) * 3 % 10;
        subMode += Math.floor(parseInt(bzRegNo.substring(8, 9)) * 5 / 10);
        subMode += parseInt(bzRegNo.substring(8, 9)) * 5 % 10;
        subMode += parseInt(bzRegNo.substring(9, 10));
        if (subMode % 10 !== 0) {
            await $c.win.alert("사업자등록번호가 잘못되었습니다.");
            return false;
        }
    }
    return true;
};



// 팝업 회신 수신 — 팝업이 남긴 인자를 as-is 함수 인자 순서로 펼쳐 넘긴다.
/**
 * @method
 * @name setZipCode_recv
 * @description 우편번호 팝업 회신 수신 — 회신값을 배열로 정규화하고, 레코드 회신(__sdd_rec 마커)이면 setZipCode 의 인자명 순서에 맞춰 값을 펼친 뒤 setZipCode 를 호출한다.
 * @param {Object} r 팝업 회신값(배열 또는 단일 레코드)
 * @returns {void}
 * @hidden N
 * @example scwin.setZipCode_recv(popupResult);
 */
scwin.setZipCode_recv = function(r) {
    if (!r) return;
    let a = Array.isArray(r) ? r : [r];
    if (a[0] && a[0].__sdd_rec) {
        const rec = a[0];
        const nm = function(s) {
            return s.replace(/_/g, '').toLowerCase();
        };
        const ps = (String(scwin.setZipCode).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function(s) {
            return s.trim();
        }).filter(Boolean);
        const nk = {};
        for (let k in rec) nk[nm(k)] = rec[k];
        a = ps.map(function(p) {
            return nk[nm(p)];
        });
    }
    try {
        scwin.setZipCode.apply(null, a);
    } catch (_e) {
        $c.exception.handleError(_e, {
            notify: 'none',
            context: 'popup-recv'
        });
    }
};
